package com.bbms.repo;
import com.bbms.domain.User; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import java.util.*;
public interface UserRepository extends JpaRepository<User,Long>{Optional<User> findByEmailIgnoreCase(String email); Optional<User> findByDemoKey(String demoKey); List<User> findByRoleOrderByCreatedAtDesc(String role); long countByRole(String role); long countByRoleAndDemoDataFalse(String role); long countByDemoDataTrue(); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select u from User u where u.id=:id") Optional<User> findByIdForUpdate(@Param("id") Long id);}
